class Solution:
    def tupleSameProduct(self, nums: list[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            for j in range(n):
                if j == i:
                    continue
                for k in range(n):
                    if k == i or k == j:
                        continue
                    for l in range(n):
                        if l == i or l == j or l == k:
                            continue
                        if nums[i] * nums[j] == nums[k] * nums[l]:
                            ans += 1
        return ans

solutions.better:
class Solution:
    def tupleSameProduct(self, nums):
        products = {}
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                p = nums[i] * nums[j]
                products[p] = products.get(p, 0) + 1
        ans = 0
        for count in products.values():
            ans += count * (count - 1) // 2 * 8
        return ans

